    addVertex: (x, y, z) => {
      ++vertexCount;
      return ChunkedArray.add3(vertices2, x, y, z);
    },
    addNormal: (x, y, z) => {
      ChunkedArray.add3(normals, x, y, z);
    },
    addGroup: (group) => {
      ChunkedArray.add(groups, group);
    },
