// src/utils/logger.ts
var formatArg = (v4) => {
  if (v4 instanceof Error) return v4.stack || v4.message || String(v4);
  if (typeof v4 === "object") {
    try {
      return JSON.stringify(v4);
    } catch {
      return String(v4);
    }
  }
  return String(v4);
};
var createLogger = (model, debug, send) => {
  const emit = send ?? ((message) => model.send(message));
  const sendLog = (level, ...args) => {
    if (!debug) return;
    try {
      emit({
        event: "js_log",
        level,
        message: args.map(formatArg).join(" ")
      });
    } catch {
    }
  };
  if (debug) {
    ["error", "warn"].forEach((level) => {
      const orig = console[level];
      console[level] = (...args) => {
        if (orig) {
          try {
            orig.apply(console, args);
          } catch {
          }
        }
        sendLog(level, ...args);
      };
    });
  }
  return sendLog;
};

